#!/usr/bin/env python3
# Solution for partitioning list L into triples a+b=c
L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]
# N = 15
# Triples solution printed to stdout

def find_partition(L):
    from itertools import combinations
    triples = []
    s = set(L)
    for a, b in combinations(L, 2):
        c = a + b
        if c in s and c != a and c != b:
            triples.append((a, b, c))
    from collections import defaultdict
    involvement = defaultdict(list)
    for t in triples:
        for x in t:
            involvement[x].append(t)
    used = set()
    result = []
    numbers = sorted(L, key=lambda x: len(involvement[x]))

    def backtrack():
        if len(used) == len(L):
            return True
        candidates = [n for n in numbers if n not in used]
        n = min(candidates, key=lambda x: len([t for t in involvement[x] if all(y not in used for y in t)]))
        for t in involvement[n]:
            a, b, c = t
            if a in used or b in used or c in used:
                continue
            used.update([a, b, c])
            result.append(t)
            if backtrack():
                return True
            used.difference_update([a, b, c])
            result.pop()
        return False

    if backtrack():
        return result
    return None

solution = find_partition(L)

if solution is None:
    print(\"No valid partition exists.\")
else:
    for triple in solution:
        print(triple)
    import json
    witness = {
        \"polarity\": \"positive\",
        \"evidence\": {\"path\": \"execution://witness\"},
        \"data\": {\"triples\": solution}
    }
    print(\"WITNESS: \" + json.dumps(witness))

