# Partition L into triples where a + b = c
L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]
N = 15

# Precompute possible pairs for each sum
pairs = {}
for i, a in enumerate(L):
    for j, b in enumerate(L):
        if i >= j:
            continue
        s = a + b
        if s in L:
            pairs.setdefault(s, []).append((a, b))

from functools import lru_cache

@lru_cache(maxsize=None)
def solve(remaining):
    if not remaining:
        return ()
    c = max(remaining)
    if c not in pairs:
        return None
    for a, b in pairs[c]:
        if a in remaining and b in remaining:
            new_rem = frozenset(remaining - {c, a, b})
            sub = solve(new_rem)
            if sub is not None:
                return ((a, b, c),) + sub
    return None

solution = solve(frozenset(L))
import json, sys

if solution:
    # Output the found triples as a witness
    print('WITNESS: ' + json.dumps({"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"triples": solution}}))
else:
    # No partition found
    print('WITNESS: ' + json.dumps({"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "proof", "argument": "No partition exists"}))
